-- Why this push happened. 'cron' = periodic sweep, 'admin' = on-demand UI button, 'register' = subscriber just joined, 'manual' = explicit API call, 'initial' = subscriber boot-time pull.
data RuntimeConfigApplyReason = RuntimeConfigApplyReasonCron | RuntimeConfigApplyReasonAdmin | RuntimeConfigApplyReasonRegister | RuntimeConfigApplyReasonManual | RuntimeConfigApplyReasonInitial
  deriving (Eq, Show)

-- Payload POSTed by the control plane to each subscriber's /internal/update-runtime-config endpoint.
data RuntimeConfigApplyRequest = RuntimeConfigApplyRequest
  { runtimeConfigApplyRequestPushId :: Text
  , runtimeConfigApplyRequestReason :: RuntimeConfigApplyReason
  , runtimeConfigApplyRequestSnapshot :: RuntimeConfigSnapshot
  } deriving (Eq, Show)

