  , runtimeConfigApplyResponsePreviousVersion :: (Maybe Int)
  , runtimeConfigApplyResponseStale :: (Maybe Bool)
  , runtimeConfigApplyResponseIgnoredVersion :: (Maybe Int)
  , runtimeConfigApplyResponseErrors :: (Maybe [Text])
  } deriving (Eq, Show)

-- One config entry. `value` is a free-form JSON value so callers can ship simple strings/numbers or richer JSON objects without rev'ing the schema.
data RuntimeConfigEntry = RuntimeConfigEntry
  { runtimeConfigEntryEnv :: RuntimeConfigEnv
  , runtimeConfigEntryScope :: Text
  , runtimeConfigEntryKey :: Text
  , runtimeConfigEntryValue :: (Maybe Text)
  , runtimeConfigEntryVersion :: Int
  , runtimeConfigEntryUpdatedAt :: Text
  , runtimeConfigEntryLabels :: (Maybe [Text])
  , runtimeConfigEntryMeta :: (Maybe Text)
  } deriving (Eq, Show)

-- Top-level namespace for every runtime-config record. Every Redis key, every snapshot, every subscriber registration is scoped to exactly one env. Stage and prod are isolated.
data RuntimeConfigEnv = RuntimeConfigEnvStage | RuntimeConfigEnvProd
  deriving (Eq, Show)

-- Payload sent by a subscriber to POST /subscribers on the control plane.
data RuntimeConfigRegisterRequest = RuntimeConfigRegisterRequest
  { runtimeConfigRegisterRequestEnv :: RuntimeConfigEnv
  , runtimeConfigRegisterRequestName :: Text
  , runtimeConfigRegisterRequestScope :: Text
  , runtimeConfigRegisterRequestApplyUrl :: Text
  , runtimeConfigRegisterRequestLabels :: (Maybe [Text])
  } deriving (Eq, Show)

-- The full set of active entries that apply to a given (env, scope) at a point in time. Subscribers receive this on every push.
data RuntimeConfigSnapshot = RuntimeConfigSnapshot
  { runtimeConfigSnapshotEnv :: RuntimeConfigEnv
  , runtimeConfigSnapshotScope :: Text
  , runtimeConfigSnapshotGeneratedAt :: Text
  , runtimeConfigSnapshotSnapshotVersion :: Int
  , runtimeConfigSnapshotEntries :: [RuntimeConfigEntry]
  } deriving (Eq, Show)

-- One long-running service that wants config pushed to it. Subscribers are env-bound: a single deployment instance can only belong to one env.
data RuntimeConfigSubscriber = RuntimeConfigSubscriber
  { runtimeConfigSubscriberEnv :: RuntimeConfigEnv
  , runtimeConfigSubscriberName :: Text
  , runtimeConfigSubscriberScope :: Text
  , runtimeConfigSubscriberApplyUrl :: Text
  , runtimeConfigSubscriberRegisteredAt :: (Maybe Text)
  , runtimeConfigSubscriberLastPushAt :: (Maybe Text)
  , runtimeConfigSubscriberLastPushOk :: (Maybe Bool)
  , runtimeConfigSubscriberLastPushError :: (Maybe Text)
  , runtimeConfigSubscriberLastAppliedVersion :: (Maybe Int)
  , runtimeConfigSubscriberLabels :: (Maybe [Text])
  } deriving (Eq, Show)

-- Payload sent by the admin UI (or any operator script) to create or update one entry. The control plane assigns the new version and updatedAt.
data RuntimeConfigUpsertRequest = RuntimeConfigUpsertRequest
  { runtimeConfigUpsertRequestEnv :: RuntimeConfigEnv
  , runtimeConfigUpsertRequestScope :: Text
  , runtimeConfigUpsertRequestKey :: Text
  , runtimeConfigUpsertRequestValue :: (Maybe Text)
  , runtimeConfigUpsertRequestLabels :: (Maybe [Text])
  , runtimeConfigUpsertRequestReason :: (Maybe Text)
  } deriving (Eq, Show)
